// The task declaration contract (per-project-scheduling DESIGN §1) — the single
// source of truth for what a `tasks/<name>/task.mjs` default export must carry.
// Both the author-time `task-declaration-shape` check and the executor-side
// `validate-dispatch` validate against this one function, so the accepted shape
// can never drift between the two surfaces.

import { FREQUENCIES } from './slots.mjs';
import { MODEL_FAMILIES } from './model-map.mjs';
import { EXECUTING_LEASH_MS } from './queue/leases.mjs';

// A declared timeout is always a whole number of seconds, > 0.
const isPositiveInt = (n) => Number.isInteger(n) && n > 0;

// A prework command must stay inside its own task directory — no absolute
// path and no `..` traversal in the command string — the same containment the
// worker-file rule gives agent_instructions (task-prework DESIGN §2).
const escapesTaskDir = (cmd) => /(^|\s)\//.test(cmd) || cmd.includes('..');

// The 2026-08-06 phase-language rename (owner): task execution is two similar,
// consecutive phases — deterministic PREWORK, then AGENTIC WORK — and the field
// names say so instead of framing the code phase as preparation for the agent.
// Legacy names stay accepted here (consumer local packs rename on their own
// clock, driven by a migration note), canonical names win when both are present.
const LEGACY_FIELDS = { agent_preprocessing: 'prework', agent_preprocessing_timeout: 'prework_timeout' };

// Return the declaration with canonical field names. Non-objects pass through
// untouched so validateTaskDeclaration still reports them. Loaders (discover,
// resolve-dispatch) normalize once; everything downstream sees only `prework`.
export function normalizeTaskDeclaration(decl) {
  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) return decl;
  const out = { ...decl };
  for (const [legacy, canonical] of Object.entries(LEGACY_FIELDS)) {
    if (out[legacy] !== undefined) {
      if (out[canonical] === undefined) out[canonical] = out[legacy];
      delete out[legacy];
    }
  }
  return out;
}

// The write ceiling a task declares (DESIGN §1, §4). A declared MAXIMUM, not a
// promise: `none` may never open a PR, `open-pr` may open but never merge,
// `merged-pr` may arm auto-merge. "No change" is always legal.
export const OUTCOMES = ['none', 'open-pr', 'merged-pr'];


// The executor-session dispatch vocabulary — DEPRECATED as a declared field, kept
// as routing. 'self' dispatches ride `ready-for-agent`; 'fleet' rides
// `ready-for-agent-fleet`, the label whose executor session holds the owner's repos.
// A task no longer declares this: a repo's executor carries the access it was
// provisioned with (the sheepdog enforcer's already spans the fleet), so the split
// protects nothing there. The one standing use is the canon home's curation tasks
// (growth-promote, growth-discover-packs), whose fleet executor is a separate,
// broader-scoped routine in that one repo.
export const SESSION_SCOPES = ['self', 'fleet'];

// What must happen to a task's work item when a recovery path would re-execute it
// (tasks-dispatch DESIGN §6). `requeue` is the safe-side default for sweep-shaped
// work; `needs-human` is the at-most-once dial a one-shot side effect declares.
export const INTERRUPT_POLICIES = ['requeue', 'needs-human'];
=====SLOTS=====
// Due-slot math for the vendored hourly scheduler (per-project-scheduling
// DESIGN §3). Pure and stateless: given the repo's `schedule` anchor, the
// frequencies its tasks declare, the current time `now`, and the timestamp
// `lastSuccess` of the scheduler's last SUCCESSFUL run (read from the Actions
// run ledger GitHub already keeps — there is no watermark file to corrupt),
// this decides exactly which frequencies are due and the slot id each is
// running under.
//
// The whole model is: consider ONLY the single most-recent scheduled slot per
// frequency, and it is due iff its time falls in `(lastSuccess, now]`.
//   - Miss / outage self-heals — the next successful run catches up the one
//     most-recent daily/weekly/monthly slot; a 3-day outage yields one catch-up
//     evaluation per frequency, never a backfill storm (DESIGN §3.1).
//   - HOURLY never catches up for free: its most-recent slot is always the
//     current hour, so an outage evaluates the current poll once and never a
//     stale one — no special case needed, the most-recent-only rule delivers it.
//   - Late / early fire is irrelevant: due-ness is schedule math, never
//     wall-clock equality with the (hashed :10–:50) cron minute.
//   - First run (`lastSuccess` null / fresh adoption) → the most-recent slot of
//     the FIRST-RUN SET only (hourly + the daily family): the immediate
//     evaluation that smoke-tests a newly-wired repo, without an off-anchor
//     weekly/monthly run on it (DESIGN §3.1, #522).
//
// `lastSuccess` null means exactly one thing — the ledger was read and holds no
// successful run. A ledger that could not be READ is never null: the caller
// (`lastSuccessTime`) throws, and the run fails rather than reach this math with
// a watermark it had to guess (#522).
//
// All times are UTC (the `schedule` values are UTC by contract, DESIGN §2). This
// module never reads the clock itself — `now` is always injected — so the whole
// due-ness decision is deterministic and testable.

// The legal frequency tokens (DESIGN §1). `task-declaration-shape` is what
// rejects anything outside this set at author time; here an unknown token is
// simply never due (defensive — the scheduler must not throw on a stray value).
//
// `manual` is the one non-cadence: a manual task is NEVER due on any schedule and
// runs only when a hand-started run forces it (`FORCE_TASKS`, run.mjs). It exists
// for operator levers — work that answers no recurring question but wants a task's
// whole apparatus (declaration, contract validation, prework, the dispatch issue)
// when a human pulls it. dueSlots skips it unconditionally; mostRecentSlot still
// resolves it, because a forced run needs a slot to run under.
export const FREQUENCIES = ['hourly', 'daily-2h', 'daily-1h', 'daily', 'daily+1h', 'weekly', 'monthly', 'manual'];

// What a FIRST run (an empty ledger — fresh adoption) evaluates. Deliberately
// not every frequency: the first run is an adoption smoke test, and the wiring
// it proves — task discovery, signal collection, the dispatch issue, the label,
// executor pickup — is identical whatever the frequency, so the daily family
// exercises all of it. Including weekly and monthly would only add an
// off-anchor run of their unconditional tasks (open-web research, pack
=====STUBS=====
# Claudinite work-item queue — the generator tick and its drain (tasks-dispatch
# DESIGN §5, §10). This is the repo's ONLY cron, and it replaces the slot
# scheduler's content at the same path when `taskScheduler.dispatch` is `"queue"`
# — same file, same hashed minute, different mechanism, so the one-cron rule and
# every reader that knows this workflow by name keep holding.
#
# A thin shim: all logic lives in the vendored engine, so this file changes
# rarely. The minute below is a placeholder; bootstrap and the wiring converge
# rewrite it to this repo's stable hashed minute in :10–:50, computed by
# `node .claudinite/shared/engine/scheduler/hash-minute.mjs <owner/repo>`.
#
# TWO JOBS, IN ORDER. The tick is pure label mechanics over the issue list —
# instantiate each task's standing item at its anchor, ready what is due, reclaim
# dead executor claims — and evaluates no precondition and collects no signal. The
# drain is an ordinary executor run: it picks up what the tick just created, which
# is what keeps the common case's latency at zero even with no `labeled` event
# delivered. Lost events are therefore never the only delivery — they are latency
# sugar, which is what retires the re-arm.
#
# `workflow_dispatch` is not a convenience: it is the never-wait-for-the-cron
# lever every forced run, migration and validation burst depends on.
name: Claudinite scheduler

on:
  schedule:
    - cron: '10 * * * *'
  workflow_dispatch:

# One tick at a time, always. The tick's duplicate-standing-item self-heal is
# written assuming exactly this — it closes every open family item but the oldest,
# which is safe precisely because two ticks never run at once.
concurrency:
  group: claudinite-tick
  cancel-in-progress: false

permissions:
  contents: write        # read the repo + vendored engine; a task's prework pushes its delivery branch
  issues: write          # create / label / comment / close work items — the queue itself
  pull-requests: write   # a task's prework opens its PR and arms auto-merge
  actions: write         # dispatch a workflow a task drives (creating a workflow_dispatch event needs write; `read` silently 403s the POST)

jobs:
  tick:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 24
      - name: Instantiate, ready and reclaim work items
        env:
          GITHUB_TOKEN: ${{ github.token }}
        run: node .claudinite/shared/engine/scheduler/queue/tick.mjs

  # The post-tick drain. `timeout-minutes` MUST stay ≤ the engine's executing
  # leash (60m): a hung runner has to be killed by the platform before its claim
  # is reaped and the item re-picked, or a zombie's prework runs beside its
  # replacement's.
  drain:
    needs: tick
    runs-on: ubuntu-latest
    timeout-minutes: 50
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 24
      - name: Drain the queue
        env:
          GITHUB_TOKEN: ${{ github.token }}
          # The wiring converge stamps every declared required_secret, and every
          # configured invocation endpoint's token, below this marker — by name.
          # claudinite:secrets
        run: node .claudinite/shared/engine/scheduler/queue/executor.mjs

  # A scheduled run reaches no one when it goes red, so escalate a whole-run
  # failure to a human-visible `workflow-failure` issue. Converges to ONE open
  # issue by a fixed title (create-or-comment), and ensures the label first since a
  # first-run failure may precede any label-ensure.
  report-failure:
    needs: [tick, drain]
    if: failure()
    runs-on: ubuntu-latest
    permissions:
      issues: write
    steps:
      - uses: actions/github-script@v7
        with:
          script: |
            const { owner, repo } = context.repo;
            const title = 'Claudinite scheduler run failed';
            await github.rest.issues.createLabel({ owner, repo, name: 'workflow-failure', color: 'b60205', description: 'Claudinite scheduler: a scheduler run or task failed' }).catch(() => {});
            const run = `${context.serverUrl}/${owner}/${repo}/actions/runs/${context.runId}`;
            const body = `The Claudinite tick/drain run failed: ${run}`;
            const found = await github.rest.search.issuesAndPullRequests({ q: `repo:${owner}/${repo} is:issue is:open in:title "${title}"` });
            if (found.data.total_count > 0) await github.rest.issues.createComment({ owner, repo, issue_number: found.data.items[0].number, body });
            else await github.rest.issues.create({ owner, repo, title, labels: ['workflow-failure'], body });

