+<!doctype html>
+<html lang="en">
+<head>
+<meta charset="utf-8">
+<meta name="viewport" content="width=device-width, initial-scale=1">
+<title>Claudinite tasks</title>
+<style>
+  /* Light is the base palette; the dark steps are their own selected values under
+     both the OS setting and an explicit toggle, never an automatic inversion. */
+  :root {
+    color-scheme: light;
+    --plane:      #f9f9f7;
+    --surface:    #fcfcfb;
+    --ink:        #0b0b0b;
+    --ink-2:      #52514e;
+    --muted:      #898781;
+    --rule:       #e1e0d9;
+    --border:     rgba(11,11,11,0.10);
+
+    --good:     #0ca30c;
+    --warning:  #fab219;
+    --serious:  #ec835a;
+    --critical: #d03b3b;
+
+    --s-blue:   #2a78d6;
+    --s-orange: #eb6834;
+    --s-aqua:   #1baf7a;
+    --s-yellow: #eda100;
+    --s-violet: #4a3aa7;
+  }
+  @media (prefers-color-scheme: dark) {
+    :root:not([data-theme="light"]) {
+      color-scheme: dark;
+      --plane:   #0d0d0d;
+      --surface: #1a1a19;
+      --ink:     #ffffff;
+      --ink-2:   #c3c2b7;
+      --muted:   #898781;
+      --rule:    #2c2c2a;
+      --border:  rgba(255,255,255,0.10);
+      --s-blue:   #3987e5;
+      --s-orange: #d95926;
+      --s-aqua:   #199e70;
+      --s-yellow: #c98500;
+      --s-violet: #9085e9;
+    }
+  }
+  :root[data-theme="dark"] {
+    color-scheme: dark;
+    --plane:   #0d0d0d;
+    --surface: #1a1a19;
+    --ink:     #ffffff;
+    --ink-2:   #c3c2b7;
+    --muted:   #898781;
+    --rule:    #2c2c2a;
+    --border:  rgba(255,255,255,0.10);
+    --s-blue:   #3987e5;
+    --s-orange: #d95926;
+    --s-aqua:   #199e70;
+    --s-yellow: #c98500;
+    --s-violet: #9085e9;
+  }
+
+  * { box-sizing: border-box; }
+  body {
+    margin: 0;
+    background: var(--plane);
+    color: var(--ink);
+    font: 14px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
+  }
+  a { color: var(--s-blue); }
+  h1 { font-size: 17px; margin: 0; letter-spacing: -0.01em; }
+  h2 { font-size: 13px; margin: 0 0 10px; color: var(--ink-2); font-weight: 600;
+       text-transform: uppercase; letter-spacing: 0.06em; }
+  .wrap { max-width: 1180px; margin: 0 auto; padding: 18px 20px 64px; }
+
+  /* --- controls --- */
+  header.bar {
+    position: sticky; top: 0; z-index: 5;
+    background: var(--surface);
+    border-bottom: 1px solid var(--rule);
+  }
+  .bar-in { max-width: 1180px; margin: 0 auto; padding: 12px 20px;
+            display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
+  .grow { flex: 1 1 auto; }
+  input, button, select {
+    font: inherit; color: var(--ink); background: var(--surface);
+    border: 1px solid var(--border); border-radius: 7px; padding: 6px 9px;
+  }
+  input { min-width: 190px; }
+  button { cursor: pointer; }
+  button:hover { border-color: var(--muted); }
+  button[disabled] { opacity: .5; cursor: default; }
+  .hint { color: var(--muted); font-size: 12px; }
+
+  /* --- stat tiles: the headline numbers, no chart needed --- */
+  .tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(148px, 1fr));
+           gap: 10px; margin-bottom: 22px; }
+  .tile { background: var(--surface); border: 1px solid var(--border);
+          border-radius: 10px; padding: 12px 14px; }
+  .tile .v { font-size: 25px; line-height: 1.15; }
+  .tile .k { font-size: 12px; color: var(--ink-2); margin-top: 2px; }
+
+  /* --- panels & tables --- */
+  section { margin-bottom: 26px; }
+  .panel { background: var(--surface); border: 1px solid var(--border);
+           border-radius: 10px; overflow: hidden; }
+  table { width: 100%; border-collapse: collapse; }
+  th { text-align: left; font-size: 11px; text-transform: uppercase;
+       letter-spacing: 0.05em; color: var(--muted); font-weight: 600;
+       padding: 9px 12px; border-bottom: 1px solid var(--rule); white-space: nowrap; }
+  td { padding: 9px 12px; border-bottom: 1px solid var(--rule); vertical-align: top; }
+  tr:last-child td { border-bottom: 0; }
+  tbody tr:hover { background: color-mix(in srgb, var(--ink) 4%, transparent); }
+  .num { font-variant-numeric: tabular-nums; }
+  .scroll { overflow-x: auto; }
+  .name { font-weight: 600; }
+  .sub { color: var(--muted); font-size: 12px; }
+
+  /* --- chips: state is identity, so it always carries its own label text --- */
+  .chip { display: inline-flex; align-items: center; gap: 5px;
+          border-radius: 999px; padding: 2px 9px; font-size: 12px;
+          border: 1px solid var(--border); white-space: nowrap; }
+  .dot { width: 7px; height: 7px; border-radius: 50%; flex: none; }
+  .chip.blocked   .dot { background: var(--s-blue); }
+  .chip.ready     .dot { background: var(--s-aqua); }
+  .chip.executing .dot { background: var(--s-yellow); }
+  .chip.agent     .dot { background: var(--s-violet); }
+  .chip.human     .dot { background: var(--critical); }
+  .chip.torn      .dot { background: var(--serious); }
+  .chip.idle      .dot { background: var(--muted); }
+  .chip.urgent { border-color: var(--critical); color: var(--critical); }
+
+  /* Warnings pair an icon with words — the color never carries it alone. */
+  .warn { display: block; font-size: 12px; margin-top: 3px; }
+  .warn.critical { color: var(--critical); }
+  .warn.serious  { color: var(--serious); }
+  .warn.warning  { color: var(--ink-2); }
+
+  /* --- the one plotted mark: a thin outcome bar per task --- */
+  .bar { display: flex; gap: 2px; height: 7px; width: 108px; }
+  .bar i { display: block; height: 100%; }
+  .bar i:first-child { border-radius: 4px 0 0 4px; }
+  .bar i:last-child  { border-radius: 0 4px 4px 0; }
+  .bar i:only-child  { border-radius: 4px; }
+  .sw { display: inline-block; width: 9px; height: 9px; border-radius: 3px;
+        vertical-align: -1px; margin-right: 5px; }
+  .legend { display: flex; gap: 14px; flex-wrap: wrap; font-size: 12px;
+            color: var(--ink-2); margin-bottom: 10px; }
+
+  .empty { padding: 22px; text-align: center; color: var(--muted); }
+  .err { border-left: 3px solid var(--critical); background: var(--surface);
+         padding: 10px 14px; border-radius: 0 8px 8px 0; margin-bottom: 14px; }
+  details.setup { background: var(--surface); border: 1px solid var(--border);
+                  border-radius: 10px; padding: 12px 14px; margin-bottom: 20px; }
+  details.setup summary { cursor: pointer; font-weight: 600; }
+  details.setup p, details.setup li { color: var(--ink-2); }
+  code { background: color-mix(in srgb, var(--ink) 7%, transparent);
+         padding: 1px 5px; border-radius: 4px; font-size: 12.5px; }
+</style>
+</head>
+<body>
+
+<header class="bar">
+  <div class="bar-in">
+    <h1>Claudinite tasks</h1>
+    <input id="repo" placeholder="owner/repo" autocomplete="off" spellcheck="false">
+    <input id="token" type="password" placeholder="GitHub token" autocomplete="off">
+    <button id="load">Load</button>
+    <span class="grow"></span>
+    <span id="rate" class="hint"></span>
+    <button id="theme" title="Toggle light / dark">◐</button>
+  </div>
+</header>
+
+<div class="wrap">
+  <div id="errors"></div>
+
+  <details class="setup" id="setup">
+    <summary>How this reads your repo</summary>
+    <p>
+      Everything happens in this browser tab. The page calls <code>api.github.com</code>
+      directly with the token you paste, so <strong>your own GitHub permissions are the
+      only access control</strong> — there is no server and no shared credential. The token
+      is kept in this browser's <code>localStorage</code> and is sent to GitHub and nowhere
+      else. A fine-grained token with <em>read-only</em> Contents, Issues and Actions on the
+      repo is enough; for a public repo you can leave it blank and use the (much smaller)
+      anonymous rate limit.
+    </p>
+    <p class="hint">
