  assert.equal(warningsFor(readyItem, NOW, { periodFor: () => 7 * day }).length, 0);
  // Hourly: 3 days is far past two — warned.
  assert.equal(warningsFor(readyItem, NOW, { periodFor: () => 3600e3 }).length, 1);
});

