const scalar = (src, field) => {
  const m = new RegExp(`^\\s*${field}:\\s*(?:'([^']*)'|"([^"]*)"|(\\d+)|(true|false))\\s*,`, 'm').exec(src);
  if (!m) return null;
  if (m[3] !== undefined) return Number(m[3]);
  if (m[4] !== undefined) return m[4] === 'true';
  return m[1] ?? m[2];
};

const stringArray = (src, field) => {
  const m = new RegExp(`^\\s*${field}:\\s*\\[([^\\]]*)\\]`, 'm').exec(src);
  if (!m) return null;
  return [...m[1].matchAll(/'([^']*)'|"([^"]*)"/g)].map((x) => x[1] ?? x[2]);
};

