// Parameterised render driver: serve the checkout, stub the GitHub API with the
// fixture, screenshot the dashboard. argv: <theme> <out.png>
import { chromium } from 'playwright';
import { readFileSync } from 'node:fs';

const theme = process.argv[2] ?? 'light';
const out = process.argv[3] ?? '/tmp/shot.png';
const fixture = readFileSync(new URL('./fixture.json', import.meta.url), 'utf8');

const browser = await chromium.launch();
const page = await browser.newPage({
  viewport: { width: 1320, height: 1400 },
  colorScheme: theme === 'dark' ? 'dark' : 'light',
});

page.on('console', (m) => { if (m.type() === 'error') console.log('PAGE ERROR:', m.text()); });
page.on('pageerror', (e) => console.log('PAGE EXCEPTION:', e.message));

// Answer api.github.com from the fixture. Everything else — the module graph, the
// derivation, the render — is the real code path.
await page.addInitScript((raw) => {
  const f = JSON.parse(raw);
  const json = (b) => new Response(JSON.stringify(b), { status: 200, headers: { 'content-type': 'application/json', 'x-ratelimit-remaining': '4873', 'x-ratelimit-limit': '5000' } });
  const text = (b) => new Response(b, { status: 200, headers: { 'x-ratelimit-remaining': '4873', 'x-ratelimit-limit': '5000' } });
  const real = window.fetch;
  window.fetch = async (url, init) => {
    const u = String(url);
    if (!u.startsWith('https://api.github.com')) return real(url, init);
    const p = u.slice('https://api.github.com'.length);
    if (/^\/repos\/[^/]+\/[^/]+$/.test(p)) return json({ default_branch: f.default_branch });
    if (p.includes('/git/trees/')) return json({ tree: f.paths.map((x) => ({ path: x, type: 'blob' })), truncated: false });
    if (p.includes('/contents/')) {
      const path = decodeURIComponent(p.split('/contents/')[1].split('?')[0]);
      return f.files[path] !== undefined ? text(f.files[path]) : new Response('{"message":"Not Found"}', { status: 404 });
    }
    if (p.includes('/issues?')) return json(new URL(u).searchParams.get('page') === '1' ? f.issues : []);
    if (p.includes('/actions/runs')) return json({ workflow_runs: f.runs });
    if (/\/issues\/\d+\/comments/.test(p)) return json([]);
    return new Response('{"message":"unstubbed"}', { status: 404 });
  };
}, fixture);

if (theme === 'dark') await page.addInitScript(() => { document.documentElement.dataset.theme = 'dark'; });

await page.goto('http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8099/dev/tools/tasks-dashboard/?repo=missingbulb/Claudinite', { waitUntil: 'load' });
await page.waitForFunction(() => document.querySelectorAll('#roster tbody tr').length > 0, { timeout: 15000 });
await page.screenshot({ path: out, fullPage: true });

const rows = await page.$$eval('#roster tbody tr', (r) => r.length);
const queue = await page.$$eval('#queue tbody tr', (r) => r.length);
const foot = await page.$eval('#footnote', (n) => n.textContent);
console.log(`${theme}: ${rows} roster rows, ${queue} queue rows\n  ${foot}`);
await browser.close();

