+      if (hit !== undefined) {
+        batch = hit;
+        fromCache += 1;
+        rate.served += 1;
+      } else {
+        const res = await raw(path, { token });
+        rate.spent += 1;
+        if (!res.ok) throw await fail(res, path);
+        const body = await res.json();
+        batch = (Array.isArray(body) ? body : []).filter((i) => !i.pull_request).map(projectIssue);
+        // A short page means the end of history, which cannot grow older; a full one
+        // is a settled window. Both are safe to keep for the TTL.
+        ageing.set(ck, batch);
+      }
+    }
+
+    // A page's raw length decides pagination, but PRs were filtered out of it, so a
+    // page of pure PRs must not read as the end. The API returns a full page unless
+    // it has genuinely run out, so only an empty projection AND an empty page stops.
+    if (batch.length === 0 && page > 1) { complete = true; break; }
+    out.push(...batch);
+    scanned += batch.length;
+    if (batch.length < perPage - 40) { complete = true; break; }
+  }
+  return { issues: out, scanned, complete, fromCache };
+}
+
+export const listRuns = (repo, token, perPage = 40) =>
+  conditional(`/repos/${repo}/actions/runs?per_page=${perPage}`, token, {
+    transform: (r) => (r.workflow_runs ?? []).map(projectRun),
+  });
+
+export const listComments = (repo, number, token) =>
+  conditional(`/repos/${repo}/issues/${number}/comments?per_page=100`, token);
+
+// Who the viewer is. Also the cheapest possible credential check — a bad token
+// fails here rather than three calls into a repo sweep.
+export const getViewer = (repo, token) =>
+  conditional('/user', token, { transform: (u) => ({ login: u.login, avatar_url: u.avatar_url, html_url: u.html_url }) });

