import { cp, mkdir, writeFile, readFile, rm, access } from 'node:fs/promises';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const ENGINE = join(ROOT, '.claudinite/shared/engine');
const SOURCE = join(ENGINE, 'scheduler/dashboard');
const OUT = join(ROOT, '_site');
// Where the dashboard ends up in the published site. It MIRRORS its path inside the
// engine, minus the `engine/` prefix, and that is load-bearing rather than tidiness:
// the page imports the queue's modules by relative path (`../queue/work-item.mjs`,
// `../../checks/helpers/…`) precisely so it cannot drift from them. Flattening the
// directory into the site root would send those imports above the root and the page
// would not boot. So the tree is staged whole and the root is a redirect.
const HOME = 'scheduler/dashboard';

const exists = async (p) => { try { await access(p); return true; } catch { return false; } };

if (!await exists(SOURCE)) {
  process.stdout.write(
    'The dashboard is not in this repo\'s mount yet '
    + '(.claudinite/shared/engine/scheduler/dashboard). Nothing to publish — the next '
    + 'converge that delivers it will make this build produce a site.\n',
  );
  process.exit(0);
}

await rm(OUT, { recursive: true, force: true });
await mkdir(OUT, { recursive: true });

// The whole engine tree, not a hand-picked subset: the page's import graph is the
// engine's business and may grow a module, and a curated copy would break silently
// the first time it did. It is all public canon source and it is all text.
await cp(ENGINE, OUT, { recursive: true });

// `serve.mjs` is a local development server and the rest is documentation. None of
// it belongs on a published site — `serve.mjs` least of all, being a file server's
// source sitting where it reads as part of the page.
for (const f of ['serve.mjs', 'oauth-exchange.example.mjs', 'dashboard.config.example.json', 'README.md']) {
  await rm(join(OUT, HOME, f), { force: true });
}

// The root sends visitors to the page. A redirect rather than a copy, because a copy
// is the flattening the imports cannot survive.
await writeFile(join(OUT, 'index.html'), `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Claudinite fleet tasks</title>
<meta http-equiv="refresh" content="0; url=./${HOME}/">
<link rel="canonical" href="./${HOME}/">
</head>
<body><p>Continue to the <a href="./${HOME}/">fleet task dashboard</a>.</p></body>
</html>
`);

// Pages runs uploaded artifacts through Jekyll unless told not to, and Jekyll drops
// files and directories beginning with an underscore.
await writeFile(join(OUT, '.nojekyll'), '');

