// Assemble the Pages site: the fleet task dashboard, pointed at every member.
//
// The dashboard itself is NOT in this repo. It is engine code, delivered into
// `.claudinite/shared/engine/scheduler/dashboard/` by the Claudinite converge, and
// this script only stages it and writes the two files a deployment owns — its
// config and its roster. So the page here is never a fork of the canon's: when the
// engine's dashboard changes, this site gets it on the next converge with no work.
//
// INERT UNTIL THE MOUNT CATCHES UP. A member's mount is whatever the last converge
// delivered, so this repo can be running this script before the dashboard exists in
// its own mount. That is an ordinary state, not a failure: the build reports it and
// exits clean, and the site publishes as soon as the mount carries the directory.
// Failing here would turn "the fleet has not converged yet" into a red workflow on
// every run until it does.

import { cp, mkdir, writeFile, readFile, rm, access } from 'node:fs/promises';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = join(ROOT, '.claudinite/shared/engine/scheduler/dashboard');
const OUT = join(ROOT, '_site');

const exists = async (p) => { try { await access(p); return true; } catch { return false; } };

if (!await exists(SOURCE)) {
  process.stdout.write(
    'The dashboard is not in this repo\'s mount yet '
    + '(.claudinite/shared/engine/scheduler/dashboard). Nothing to publish — the next '
    + 'converge that delivers it will make this build produce a site.\n',
  );
  process.exit(0);
}

await rm(OUT, { recursive: true, force: true });
await mkdir(OUT, { recursive: true });
await cp(SOURCE, OUT, { recursive: true });

// `serve.mjs` is a local development server and the example files are documentation.
// None of them belong on a public site, and `serve.mjs` in particular reads from
// disk — publishing it would be publishing a file server's source as if it were part
// of the page.
for (const f of ['serve.mjs', 'oauth-exchange.example.mjs', 'dashboard.config.example.json', 'README.md']) {
  await rm(join(OUT, f), { force: true });
}

// --- the roster -----------------------------------------------------------------

// Members come from the fleet artifact this repo already maintains rather than from
// a hand-kept list: a second list would drift, and no repo list may live in code.
// A missing or unreadable artifact yields an empty roster, which is a dashboard with
// no picker rather than a broken build.
async function roster() {
  try {
    const doc = JSON.parse(await readFile(join(ROOT, 'usage-fleet.GENERATED.json'), 'utf8'));
    const names = doc?.repos && typeof doc.repos === 'object' ? Object.keys(doc.repos) : [];
    return names.filter((n) => /^[^/\s]+\/[^/\s]+$/.test(n)).sort();
  } catch {
    return [];
  }
}

const repos = await roster();
// Only the names travel. The usage artifact is ~450KB of statistics the dashboard
// never reads, and a page should not download it to populate a dropdown.
await writeFile(join(OUT, 'fleet-roster.GENERATED.json'), `${JSON.stringify({ repos }, null, 2)}\n`);

// --- the config -----------------------------------------------------------------

// Sign-in is configured through repository VARIABLES, not secrets: a client id and
// an endpoint URL are both public by construction — they ship inside the page — and
// storing them as secrets would only make them harder to see. The actual secret
// lives in the exchange endpoint's own deployment and never comes near this repo.
//
// Both unset is a valid site: the dashboard falls back to a pasted token.
const clientId = process.env.DASHBOARD_CLIENT_ID?.trim() || null;
const exchangeUrl = process.env.DASHBOARD_EXCHANGE_URL?.trim() || null;
const config = {
  clientId,
  exchangeUrl,
  redirectUri: process.env.DASHBOARD_REDIRECT_URI?.trim() || null,
  rosterUrl: './fleet-roster.GENERATED.json',
  defaultRepo: repos[0] ?? null,
};
await writeFile(join(OUT, 'dashboard.config.json'), `${JSON.stringify(config, null, 2)}\n`);

// Say which mode the site actually built in. Sign-in silently not being configured
// is exactly the kind of thing that goes unnoticed until someone asks why they are
// being asked for a token.
process.stdout.write(
  `Built ${OUT} with ${repos.length} member(s) in the roster.\n`
  + `Sign-in: ${clientId && exchangeUrl ? 'configured' : 'NOT configured — the site will ask for a token'}`
  + `${clientId && !exchangeUrl ? ' (client id set, exchange url missing)' : ''}`
  + `${!clientId && exchangeUrl ? ' (exchange url set, client id missing)' : ''}\n`,
);

