1	import { test, beforeEach } from 'node:test';
2	import assert from 'node:assert/strict';
3	
4	class Mem {
5	  constructor() { this.m = new Map(); }
6	  get length() { return this.m.size; }
7	  key(i) { return [...this.m.keys()][i] ?? null; }
8	  getItem(k) { return this.m.has(k) ? this.m.get(k) : null; }
9	  setItem(k, v) { this.m.set(k, String(v)); }
10	  removeItem(k) { this.m.delete(k); }
11	}
12	
13	const res = (body, { status = 200, headers = {}, text = false } = {}) => ({
14	  ok: status >= 200 && status < 300,
15	  status,
16	  headers: { get: (k) => headers[k.toLowerCase()] ?? null },
17	  json: async () => body,
18	  text: async () => (text ? body : JSON.stringify(body)),
19	});
20	
21	const RATE = { 'x-ratelimit-remaining': '4321', 'x-ratelimit-limit': '5000' };
22	// A full page, so pagination continues past it — a short page legitimately means
23	// the end of history.
24	const fullPage = (n = 100) => Array.from({ length: n }, (_, i) => ({ number: i + 1, title: `i${i}`, state: 'closed', labels: [], body: '' }));
25	
26	const load = () => import(`../../../engine/scheduler/dashboard/github.mjs?t=${Math.random()}`);
27	
28	beforeEach(() => { globalThis.localStorage = new Mem(); });
29	
30	// The bug this pins: `Number(null)` is 0 and passes isFinite, so a response with no
31	// rate-limit header used to record a budget of ZERO. Every content read comes back
32	// without those headers, so the last one always won and the page reported the viewer
33	// as rate-limited when they had thousands of calls left.
34	test('a response without rate-limit headers leaves the known budget alone', async () => {
35	  const gh = await load();
36	  const calls = [];
37	  globalThis.fetch = async (url) => {
38	    calls.push(url);
39	    return url.includes('/contents/')
40	      ? res('file body', { headers: {}, text: true })          // no rate headers
41	      : res({ default_branch: 'main' }, { headers: RATE });
42	  };
43	
44	  await gh.getRepo('o/r', 't');
45	  assert.equal(gh.rate.remaining, 4321);
46	  await gh.getTextAtSha('o/r', 'sha1', 'a.json', 't');
47	  assert.equal(gh.rate.remaining, 4321, 'a header-less response must not zero the budget');
48	});
49	
50	test('a malformed rate-limit header is ignored rather than believed', async () => {
51	  const gh = await load();
52	  globalThis.fetch = async () => res({ default_branch: 'main' }, { headers: { 'x-ratelimit-remaining': 'lots' } });
53	  await gh.getRepo('o/r', 't');
54	  assert.equal(gh.rate.remaining, null);
55	});
56	
57	// The whole point of the sha key: an unchanged head means no content calls at all.
58	test('content at a sha is fetched once and served from cache after', async () => {
59	  const gh = await load();
60	  let hits = 0;
61	  globalThis.fetch = async () => { hits += 1; return res('declaration', { headers: RATE, text: true }); };
62	
63	  assert.equal(await gh.getTextAtSha('o/r', 'sha1', 'task.mjs', 't'), 'declaration');
64	  assert.equal(await gh.getTextAtSha('o/r', 'sha1', 'task.mjs', 't'), 'declaration');
65	  assert.equal(hits, 1, 'the second read never touched the network');
66	  assert.equal(gh.rate.spent, 1);
67	  assert.equal(gh.rate.served, 1);
68	
69	  await gh.getTextAtSha('o/r', 'sha2', 'task.mjs', 't');
70	  assert.equal(hits, 2, 'a new sha is a new fetch');
71	});
72	
73	// A 404 is an answer — an unadopted member has no declaration — and caching it is
74	// what stops a fleet sweep re-asking every member on every load.
75	test('a 404 is cached as a real absence', async () => {
76	  const gh = await load();
77	  let hits = 0;
78	  globalThis.fetch = async () => { hits += 1; return res({ message: 'Not Found' }, { status: 404, headers: RATE }); };
79	
80	  assert.equal(await gh.getTextAtSha('o/r', 'sha1', 'nope.json', 't'), null);
81	  assert.equal(await gh.getTextAtSha('o/r', 'sha1', 'nope.json', 't'), null);
82	  assert.equal(hits, 1, 'the absence was cached, not re-asked');
83	});
84	
85	// A 304 is the free path: GitHub does not charge it, so it must be counted apart
86	// from calls that actually spent budget.
87	test('a 304 returns the cached body and is counted as revalidated, not spent', async () => {
88	  const gh = await load();
89	  let sentEtag = null;
90	  globalThis.fetch = async (_url, init) => {
91	    sentEtag = init.headers['If-None-Match'];
92	    return sentEtag
93	      ? res(null, { status: 304, headers: RATE })
94	      : res({ default_branch: 'main', private: false, full_name: 'o/r' }, { headers: { ...RATE, etag: 'W/"v1"' } });
95	  };
96	
97	  const first = await gh.getRepo('o/r', 't');
98	  assert.equal(gh.rate.spent, 1);
99	
100	  gh.resetCounters();
101	  const second = await gh.getRepo('o/r', 't');
102	  assert.equal(sentEtag, 'W/"v1"', 'the stored etag was sent back');
103	  assert.deepEqual(second, first, 'the cached body is returned unchanged');
104	  assert.equal(gh.rate.spent, 0, 'a 304 spends no budget');
105	  assert.equal(gh.rate.revalidated, 1);
106	});
107	
108	test('an error status becomes a GitHubError carrying the status', async () => {
109	  const gh = await load();
110	  globalThis.fetch = async () => res({ message: 'Bad credentials' }, { status: 401, headers: RATE });
111	  await assert.rejects(() => gh.getRepo('o/r', 'bad'), (e) => {
112	    assert.equal(e.status, 401);
113	    assert.match(e.message, /Bad credentials/);
114	    return true;
115	  });
116	});
117	
118	// Page 1 holds every open item, so it must never come from a TTL cache; later pages
119	// are settled history and must not be refetched within the TTL.
120	test('issue page 1 is revalidated while history pages are served from the ttl cache', async () => {
121	  const gh = await load();
122	  const seen = [];
123	  globalThis.fetch = async (url, init) => {
124	    // Match on the PARSED page param: the string "page=1" is also a substring of
125	    // "per_page=100", which silently matched every page.
126	    seen.push({ page: new URL(url).searchParams.get('page'), cond: Boolean(init.headers['If-None-Match']) });
127	    const page = new URL(url).searchParams.get('page');
128	    if (page === '1') {
129	      return init.headers['If-None-Match']
130	        ? res(null, { status: 304, headers: RATE })
131	        : res(fullPage(), { headers: { ...RATE, etag: 'W/"p1"' } });
132	    }
133	    return res([], { headers: RATE });
134	  };
135	
136	  await gh.listIssues('o/r', 't', { pages: 3 });
137	  const firstRoundPageOne = seen.filter((s) => s.page === '1').length;
138	  assert.equal(firstRoundPageOne, 1);
139	
140	  gh.resetCounters();
141	  seen.length = 0;
142	  await gh.listIssues('o/r', 't', { pages: 3 });
143	  assert.ok(seen.some((s) => s.page === '1' && s.cond), 'page 1 is re-asked conditionally every time');
144	  assert.equal(gh.rate.spent, 0, 'and nothing was actually spent');
145	});
146	
