50	
51	// Whether a member's mount is current. Judged on `ref` / `engineVersion` /
52	// `packVersions` and NEVER on `updated` alone: a held stamp pins `updated` behind a
53	// pending note while the mount keeps converging normally, so a member that is fine
54	// looks weeks stale by that field.
55	//
56	// `canon` is the reference to compare against, and it is optional — with no canon
57	// supplied the honest answer is `unknown`, not `current`.
58	export function mountState(stamp, canon = null, now = null) {
59	  if (!stamp) return { state: 'none', ref: null, engineVersion: null };
60	  const ref = stamp.ref ?? null;
61	  const engineVersion = stamp.engineVersion ?? null;
62	  const updated = stamp.updated ?? null;
63	
64	  if (!canon?.ref) {
65	    // No reference to compare with. `updated` cannot decide freshness, but a mount
66	    // that has not been touched in a week says something on its own: the converge
67	    // itself has stopped, whatever version it stopped on.
68	    const age = now && updated ? ms(now) - ms(updated) : null;
69	    if (age !== null && age >= MOUNT_STALE_MS) {
