25	
26	const load = () => import(`../../../engine/scheduler/dashboard/github.mjs?t=${Math.random()}`);
27	
28	beforeEach(() => { globalThis.localStorage = new Mem(); });
29	
30	// The bug this pins: `Number(null)` is 0 and passes isFinite, so a response with no
31	// rate-limit header used to record a budget of ZERO. Every content read comes back
32	// without those headers, so the last one always won and the page reported the viewer
33	// as rate-limited when they had thousands of calls left.
34	test('a response without rate-limit headers leaves the known budget alone', async () => {
35	  const gh = await load();
36	  const calls = [];
37	  globalThis.fetch = async (url) => {
38	    calls.push(url);
39	    return url.includes('/contents/')
40	      ? res('file body', { headers: {}, text: true })          // no rate headers
41	      : res({ default_branch: 'main' }, { headers: RATE });
42	  };
43	
44	  await gh.getRepo('o/r', 't');
45	  assert.equal(gh.rate.remaining, 4321);
46	  await gh.getTextAtSha('o/r', 'sha1', 'a.json', 't');
47	  assert.equal(gh.rate.remaining, 4321, 'a header-less response must not zero the budget');
48	});
49	
50	test('a malformed rate-limit header is ignored rather than believed', async () => {
51	  const gh = await load();
52	  globalThis.fetch = async () => res({ default_branch: 'main' }, { headers: { 'x-ratelimit-remaining': 'lots' } });
53	  await gh.getRepo('o/r', 't');
54	  assert.equal(gh.rate.remaining, null);
55	});
56	
57	// The whole point of the sha key: an unchanged head means no content calls at all.
58	test('content at a sha is fetched once and served from cache after', async () => {
59	  const gh = await load();
60	  let hits = 0;
61	  globalThis.fetch = async () => { hits += 1; return res('declaration', { headers: RATE, text: true }); };
62	
63	  assert.equal(await gh.getTextAtSha('o/r', 'sha1', 'task.mjs', 't'), 'declaration');
64	  assert.equal(await gh.getTextAtSha('o/r', 'sha1', 'task.mjs', 't'), 'declaration');
65	  assert.equal(hits, 1, 'the second read never touched the network');
66	  assert.equal(gh.rate.spent, 1);
67	  assert.equal(gh.rate.served, 1);
68	
69	  await gh.getTextAtSha('o/r', 'sha2', 'task.mjs', 't');
70	  assert.equal(hits, 2, 'a new sha is a new fetch');
71	});
