161	  await gh.listIssues('o/r', 't', { pages: 2 });
162	  assert.equal(historyFetches, 1);
163	  await gh.listIssues('o/r', 't', { pages: 2, historyTtl: 0 });   // nothing is fresh at ttl 0
164	  assert.equal(historyFetches, 2);
165	});

